import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Fields and Data Bindings in AL","description":"","frontmatter":{},"headers":[],"relativePath":"pages-and-user-interfaces/fields-and-data-bindings.md","filePath":"pages-and-user-interfaces/fields-and-data-bindings.md"}`),a={name:`pages-and-user-interfaces/fields-and-data-bindings.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="fields-and-data-bindings-in-al" tabindex="-1">Fields and Data Bindings in AL <a class="header-anchor" href="#fields-and-data-bindings-in-al" aria-label="Permalink to “Fields and Data Bindings in AL”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>In the previous topic, we learned that <strong>Field controls</strong> are used to display information on a page.</p><p>But how does a field control know which data to display?</p><p>For example, suppose we have a <code>Product</code> table containing the following fields:</p><ul><li>No.</li><li>Name</li><li>Unit Price</li><li>Inventory</li></ul><p>We want to display these fields on a Product Card page.</p><p>How do we connect the page controls to the corresponding table fields?</p><p>This is where <strong>Data Binding</strong> comes in.</p><p>Data binding is the process of connecting a page control to a data source so that the control can display, and potentially modify, the underlying data.</p><p>In Business Central, page fields commonly bind directly to fields in their source table.</p><h2 id="understanding-field-controls" tabindex="-1">Understanding Field Controls <a class="header-anchor" href="#understanding-field-controls" aria-label="Permalink to “Understanding Field Controls”">​</a></h2><p>A field control is declared using the <code>field</code> keyword.</p><p>The general syntax is:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(ControlName; SourceExpression)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Properties</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>There are two important components:</p><table tabindex="0"><thead><tr><th>Component</th><th>Description</th></tr></thead><tbody><tr><td><code>ControlName</code></td><td>Identifies the field control within the page.</td></tr><tr><td><code>SourceExpression</code></td><td>Specifies the data that the control displays or interacts with.</td></tr></tbody></table><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(Name; Rec.Name)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ul><li><code>Name</code> is the control name.</li><li><code>Rec.Name</code> specifies the data source.</li><li><code>ApplicationArea = All</code> makes the control available across all application areas.</li></ul><p>Notice that the control name and the source expression do not necessarily have to be identical.</p><p>You could also write:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(ProductName; Rec.Name)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Product Name&#39;;</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The control is called <code>ProductName</code>, but it is still connected to the <code>Name</code> field in the source table.</p><h2 id="understanding-rec" tabindex="-1">Understanding Rec <a class="header-anchor" href="#understanding-rec" aria-label="Permalink to “Understanding Rec”">​</a></h2><p>One of the most important concepts when working with page fields is <code>Rec</code>.</p><p><strong><code>Rec</code> is a system-defined record variable that represents the current record being displayed or processed by the page.</strong></p><p>You don&#39;t need to declare it yourself. Business Central automatically provides it for page objects.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(Name; Rec.Name)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s break this down:</p><ul><li><code>Rec</code> represents the current record.</li><li><code>Name</code> identifies a field belonging to that record.</li><li><code>Rec.Name</code> accesses the value stored in the <code>Name</code> field of the current record.</li></ul><h3 id="practical-example" tabindex="-1">Practical Example <a class="header-anchor" href="#practical-example" aria-label="Permalink to “Practical Example”">​</a></h3><p>Suppose our Product table contains these records:</p><table tabindex="0"><thead><tr><th>No.</th><th>Name</th><th style="text-align:right;">Unit Price</th></tr></thead><tbody><tr><td>P001</td><td>Laptop</td><td style="text-align:right;">75000</td></tr><tr><td>P002</td><td>Keyboard</td><td style="text-align:right;">2500</td></tr><tr><td>P003</td><td>Mouse</td><td style="text-align:right;">1200</td></tr></tbody></table><p>If a user opens the Product Card for product <code>P001</code>, the <code>Rec</code> variable represents that particular product record.</p><p>Therefore:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Rec.&quot;No.&quot;       // P001</span></span>
<span class="line"><span>Rec.Name        // Laptop</span></span>
<span class="line"><span>Rec.&quot;Unit Price&quot; // 75000</span></span></code></pre></div><p>If the user opens product <code>P002</code>, <code>Rec</code> represents that record instead.</p><p><strong>Important:</strong> <code>Rec</code> is not a particular product or a particular table field. It represents the current record associated with the page&#39;s <code>SourceTable</code>.</p><p>Microsoft also provides <code>xRec</code>, which represents the original version of a record before modifications. We&#39;ll explore that when we cover table and page triggers.</p><h2 id="binding-page-fields-to-table-fields" tabindex="-1">Binding Page Fields to Table Fields <a class="header-anchor" href="#binding-page-fields-to-table-fields" aria-label="Permalink to “Binding Page Fields to Table Fields”">​</a></h2><p>Let&#39;s put what we&#39;ve learned into practice.</p><p>Suppose we have a <code>Product</code> table and want to display its information on a Product Card page.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50100 ProductCard</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = Card;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span>    Caption = &#39;Product Card&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            group(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                field(&quot;No.&quot;; Rec.&quot;No.&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Name; Rec.Name)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(&quot;Unit Price&quot;; Rec.&quot;Unit Price&quot;)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                field(Inventory; Rec.Inventory)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s examine what happens:</p><ol><li><code>SourceTable = Product</code> establishes the Product table as the page&#39;s data source.</li><li>Business Central retrieves the current Product record.</li><li><code>Rec</code> represents that record.</li><li>Each field control accesses its corresponding field through <code>Rec</code>.</li><li>Business Central displays the retrieved values on the page.</li></ol><p>The important relationship is:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Product Table</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     | SourceTable = Product</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>Product Card Page</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     | Rec.&quot;No.&quot;</span></span>
<span class="line"><span>     | Rec.Name</span></span>
<span class="line"><span>     | Rec.&quot;Unit Price&quot;</span></span>
<span class="line"><span>     | Rec.Inventory</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>Page Field Controls</span></span></code></pre></div><h3 id="what-happens-when-a-user-edits-a-field" tabindex="-1">What happens when a user edits a field? <a class="header-anchor" href="#what-happens-when-a-user-edits-a-field" aria-label="Permalink to “What happens when a user edits a field?”">​</a></h3><p>When a user modifies an editable field that is bound to a table field, Business Central can update the underlying record.</p><p>For example, suppose a user changes the product name from <code>Laptop</code> to <code>Gaming Laptop</code>.</p><p>The change is applied to the corresponding field in the Product record and saved according to the page&#39;s normal record-saving behavior.</p><p>This is one of the major benefits of binding page controls directly to table fields: Business Central handles much of the interaction between the user interface and the database.</p><h2 id="binding-page-fields-to-variables" tabindex="-1">Binding Page Fields to Variables <a class="header-anchor" href="#binding-page-fields-to-variables" aria-label="Permalink to “Binding Page Fields to Variables”">​</a></h2><p>Not every page field has to be connected directly to a table field.</p><p>You can also bind a page field to an AL variable.</p><p>This is useful when displaying temporary values, calculated information, or values that aren&#39;t stored directly in the source table.</p><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>page 50101 ProductInformation</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    PageType = Card;</span></span>
<span class="line"><span>    SourceTable = Product;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        area(Content)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            group(General)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                field(ProductName; ProductName)</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    ApplicationArea = All;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        ProductName: Text[100];</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Notice the difference:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(Name; Rec.Name)</span></span></code></pre></div><p>Here, the control is bound to a field in the current table record.</p><p>However:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(ProductName; ProductName)</span></span></code></pre></div><p>Here, the control is bound to an AL variable.</p><p><strong>Important distinction:</strong></p><ul><li>A control bound to <code>Rec.Name</code> accesses data from the current table record.</li><li>A control bound to <code>ProductName</code> accesses an AL variable.</li></ul><p>Changing a variable-bound control does not automatically save its value to the source table. You must implement the necessary AL logic if you want to persist that value.</p><h2 id="common-properties-of-page-fields" tabindex="-1">Common Properties of Page Fields <a class="header-anchor" href="#common-properties-of-page-fields" aria-label="Permalink to “Common Properties of Page Fields”">​</a></h2><p>Page field controls support several properties that determine their appearance and behavior.</p><p>Here are some important ones:</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>Caption</code></td><td>Specifies the user-facing label of the field.</td></tr><tr><td><code>ToolTip</code></td><td>Provides additional information when users hover over the field.</td></tr><tr><td><code>ApplicationArea</code></td><td>Determines the application areas in which the field is available.</td></tr><tr><td><code>Editable</code></td><td>Determines whether users can modify the field through the control.</td></tr><tr><td><code>Visible</code></td><td>Determines whether the field is displayed.</td></tr><tr><td><code>Enabled</code></td><td>Determines whether users can interact with the field.</td></tr><tr><td><code>Importance</code></td><td>Specifies the importance of a field, influencing how it is presented in certain layouts.</td></tr><tr><td><code>ShowMandatory</code></td><td>Displays a visual indicator showing that the field should contain a value.</td></tr><tr><td><code>Style</code></td><td>Specifies the visual formatting of the field.</td></tr><tr><td><code>MultiLine</code></td><td>Determines whether a field supports multiple lines of text.</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(Name; Rec.Name)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>    Caption = &#39;Product Name&#39;;</span></span>
<span class="line"><span>    ToolTip = &#39;Specifies the name of the product.&#39;;</span></span>
<span class="line"><span>    Editable = true;</span></span>
<span class="line"><span>    ShowMandatory = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>In this example:</p><ul><li>The field is labelled <code>Product Name</code>.</li><li>Users can hover over it to see additional information.</li><li>Users can edit its value.</li><li>A mandatory indicator is displayed.</li></ul><p><strong>Important:</strong> <code>ShowMandatory</code> only displays a visual indicator. It does not enforce data validation. For actual validation, you need appropriate table-field properties or validation logic.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li>Field controls are declared using the <code>field</code> keyword.</li><li>The <code>SourceExpression</code> determines where a page field gets its data.</li><li><code>Rec</code> is a system-defined variable representing the current record.</li><li><code>SourceTable</code> establishes the table associated with a page.</li><li><code>Rec.FieldName</code> accesses a particular field in the current record.</li><li>Page fields can bind to table fields or AL variables.</li><li>Changes to table-bound fields can be saved to the underlying record.</li><li>Changes to variable-bound fields are not automatically persisted to the database.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ol><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-system-defined-variables" target="_blank" rel="noreferrer">Microsoft Learn – System-Defined Variables</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-properties" target="_blank" rel="noreferrer">Microsoft Learn – Page Properties</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-object" target="_blank" rel="noreferrer">Microsoft Learn – Page Objects</a></li></ol>`,84)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};